const memoryWindow = parseInt(node.properties.memoryWindow?.value || 10);

helpers.log('[Input History Memory] Loading from data.history');

const messages = [];

if (data && data.history) {
  try {
    const userHist = Array.isArray(data.history.user) ? data.history.user : [];
    const agentHist = Array.isArray(data.history.agent) ? data.history.agent : [];

    const start = Math.max(0, Math.max(userHist.length, agentHist.length) - memoryWindow);

    for (let i = start; i < Math.max(userHist.length, agentHist.length); i++) {
      const u = userHist[i];
      const a = agentHist[i];

      if (u !== undefined) {
        messages.push({ role: 'user', content: String(u) });
      }
      if (a !== undefined) {
        messages.push({ role: 'assistant', content: String(a) });
      }
    }

    helpers.log(`Loaded ${messages.length} messages from input history`);
  } catch (e) {
    helpers.error(`Input history load failed: ${e.message}`);
  }
} else {
  helpers.warn('No history data found in input');
}

return {
  messages,
  chatId: data?.chatId,
  sessionId: data?.sessionId || 'default',
  memoryWindow,
  type: 'input_history'
};
